insert into public.learning_paths (id, title, description, lesson_ids, sort_order) values
('beginner', 'Complete Beginner', 'Everyday money first, then a clear look at how markets work.', array['budgeting', 'saving', 'emergency-fund', 'stock-market', 'how-stocks-work', 'etfs', 'diversification', 'compound-interest']::text[], 0),
('fundamentals', 'Investing Fundamentals', 'Stocks, ETFs, dividends, prices, and where trades actually happen.', array['stock-market', 'how-stocks-work', 'etfs', 'dividends', 'compound-growth', 'market-cap', 'stock-prices', 'primary-secondary']::text[], 1),
('explorer', 'Market Explorer', 'Cycles, company numbers, and the forces that move prices.', array['bull-bear', 'market-cycles', 'supply-demand', 'company-fundamentals', 'financial-statements', 'pe-ratio', 'revenue-earnings', 'economic-indicators']::text[], 2),
('personal', 'Personal Finance', 'Budgets, saving, credit, debt, and a plan you can revisit.', array['budgeting', 'saving', 'emergency-fund', 'credit-scores', 'debt', 'interest-rates', 'compound-interest', 'financial-planning']::text[], 3),
('advanced', 'Advanced Investor Education', 'Risk, allocation, volatility, and how a portfolio behaves over time.', array['diversification', 'asset-allocation', 'investment-risk', 'rebalancing', 'long-term', 'volatility', 'risk-return', 'financial-statements', 'pe-ratio']::text[], 4) on conflict (id) do update set title = excluded.title, description = excluded.description, lesson_ids = excluded.lesson_ids, sort_order = excluded.sort_order;
