insert into public.quiz_questions (id, lesson_id, prompt, kind, choices, answer, explanation, sort_order) values
('stock-market-s', 'stock-market', 'A friend says the stock market is a place where the company pays you a fixed amount every year, like a savings bond. What is the accurate response?', 'mcq', '[{"id":"a","text":"That is right. Shares pay a guaranteed yearly amount."},{"id":"b","text":"Shares are ownership. Any cash the company pays is not guaranteed, and the sale price can fall."},{"id":"c","text":"The market only exists so companies can buy their own products."},{"id":"d","text":"Prices are set once a year by the government."}]'::jsonb, '"b"'::jsonb, 'Stocks are ownership claims. Dividends and prices can change. They are not a promised fixed payment.', 0),
('stock-market-q1', 'stock-market', 'The stock market is one physical room where every US trade happens.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Trading happens across electronic venues and exchanges. There is no single room that is “the market.”', 1),
('stock-market-q2', 'stock-market', 'After a company has already sold new shares, later trades of those shares are mostly between:', 'mcq', '[{"id":"a","text":"The company and a bank only"},{"id":"b","text":"Investors who already hold or want the shares"},{"id":"c","text":"The tax authority and the exchange"},{"id":"d","text":"Employees and customers of the store"}]'::jsonb, '"b"'::jsonb, 'In the secondary market, investors trade existing shares with each other. The company does not receive the cash from those later trades.', 2),
('stock-market-q3', 'stock-market', 'A displayed share price is best described as:', 'mcq', '[{"id":"a","text":"A government-guaranteed value"},{"id":"b","text":"The amount of cash inside the company"},{"id":"c","text":"A record of trading interest, such as a recent trade or quote"},{"id":"d","text":"The company’s profit this year"}]'::jsonb, '"c"'::jsonb, 'A price is a market record. It is not the company’s cash balance and it is not a guarantee.', 3),
('how-stocks-work-s', 'how-stocks-work', 'You own shares and the company has a bad year. Which statement fits how common stock works?', 'mcq', '[{"id":"a","text":"The exchange must refund your purchase."},{"id":"b","text":"Your ownership claim can become less valuable because you are paid after other obligations."},{"id":"c","text":"Your shares convert into a loan the company must repay you."},{"id":"d","text":"The price is frozen until the company recovers."}]'::jsonb, '"b"'::jsonb, 'Common shareholders are last in line. A weak business can reduce what buyers will pay for the shares.', 0),
('how-stocks-work-q1', 'how-stocks-work', 'Owning common stock means the company owes you a fixed repayment date.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A loan has a repayment claim. Common stock is ownership, not a dated IOU.', 1),
('how-stocks-work-q2', 'how-stocks-work', 'The most direct reason a last trade price changes is:', 'mcq', '[{"id":"a","text":"A new trade is agreed at a different price"},{"id":"b","text":"The logo of the company changes"},{"id":"c","text":"The market closes for lunch"},{"id":"d","text":"A chart pattern completes itself"}]'::jsonb, '"a"'::jsonb, 'Prices printed on a tape are trades or quotes. A new agreed price is what updates the last trade.', 2),
('how-stocks-work-q3', 'how-stocks-work', 'Match each idea to its meaning.', 'match', '[{"term":"Common stock","definition":"Ownership claim paid after other obligations"},{"term":"Last trade","definition":"The most recent price buyers and sellers agreed"},{"term":"Dividend","definition":"Cash a company may choose to pay owners"}]'::jsonb, '{"Common stock":"Ownership claim paid after other obligations","Last trade":"The most recent price buyers and sellers agreed","Dividend":"Cash a company may choose to pay owners"}'::jsonb, 'Stock is ownership, a last trade is an agreed price, and a dividend is an optional cash distribution.', 3),
('etfs-s', 'etfs', 'Someone says, “Every index fund is an ETF, so they all trade all day.” What should you correct?', 'mcq', '[{"id":"a","text":"Nothing. The words mean the same thing."},{"id":"b","text":"An index fund can be an ETF or a mutual fund. Only the ETF version trades through the day."},{"id":"c","text":"ETFs are priced once a month."},{"id":"d","text":"Index funds hold only one company."}]'::jsonb, '"b"'::jsonb, 'Index tracking describes the strategy. ETF describes a traded fund structure. They overlap, but they are not the same word.', 0),
('etfs-q1', 'etfs', 'Buying one share of a broad stock ETF usually means:', 'mcq', '[{"id":"a","text":"You bought a single company"},{"id":"b","text":"You bought a share of a fund that holds many securities"},{"id":"c","text":"You lent money to the exchange"},{"id":"d","text":"You are guaranteed the index’s past return"}]'::jsonb, '"b"'::jsonb, 'The ETF share is a claim on the fund. The fund, not you directly, holds the basket.', 1),
('etfs-q2', 'etfs', 'A traditional mutual fund and an ETF are priced in exactly the same way during the day.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Mutual funds are commonly priced once a day. ETF shares trade through the session.', 2),
('etfs-q3', 'etfs', 'Match the term to the description.', 'match', '[{"term":"ETF","definition":"A fund whose shares trade on an exchange"},{"term":"Index fund","definition":"A fund that tracks a published list of securities"},{"term":"Mutual fund","definition":"A pooled fund commonly priced once a day"}]'::jsonb, '{"ETF":"A fund whose shares trade on an exchange","Index fund":"A fund that tracks a published list of securities","Mutual fund":"A pooled fund commonly priced once a day"}'::jsonb, 'Structure and strategy are different ideas. An index fund can use more than one structure.', 3),
('dividends-s', 'dividends', 'A share is about to go ex-dividend for $1. A classmate says the $1 is free money on top of an unchanged share price. What is the better explanation?', 'mcq', '[{"id":"a","text":"The cash leaves the company, so the share is often worth about $1 less, all else equal."},{"id":"b","text":"The exchange adds $1 to the price as a reward."},{"id":"c","text":"Dividends are interest on a loan."},{"id":"d","text":"Only bondholders receive dividends."}]'::jsonb, '"a"'::jsonb, 'The dividend is a transfer of value from the company to the shareholder, not new value created at the opening auction.', 0),
('dividends-q1', 'dividends', 'A company is required to raise its dividend every year.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Dividends are declared by the company. They can stay flat, rise, or be cut.', 1),
('dividends-q2', 'dividends', 'All else equal, paying a dividend does which of these?', 'mcq', '[{"id":"a","text":"Moves cash from the company to shareholders"},{"id":"b","text":"Increases the company’s cash"},{"id":"c","text":"Erases the shareholder’s ownership"},{"id":"d","text":"Sets the share price for the next year"}]'::jsonb, '"a"'::jsonb, 'The company distributes cash it already had. Ownership remains, but the company holds less cash.', 2),
('dividends-q3', 'dividends', 'A high dividend yield by itself tells you:', 'mcq', '[{"id":"a","text":"The company is safe"},{"id":"b","text":"The price will rise"},{"id":"c","text":"Only that the latest dividend is large relative to the current price"},{"id":"d","text":"The shares are a savings account"}]'::jsonb, '"c"'::jsonb, 'Yield is a ratio. It does not settle the question of business quality or future payments.', 3),
('compound-growth-s', 'compound-growth', 'Two illustrations start at $1,000. One earns a hypothetical 5% and withdraws the gain each year. The other leaves the gain invested at the same hypothetical 5%. After many years, why can the second be larger?', 'mcq', '[{"id":"a","text":"Because later returns apply to a bigger balance"},{"id":"b","text":"Because the market is required to pay 5%"},{"id":"c","text":"Because withdrawn gains are illegal"},{"id":"d","text":"Because prices cannot fall in the second account"}]'::jsonb, '"a"'::jsonb, 'Leaving gains invested is what lets later growth apply to earlier growth. The 5% is still only a model.', 0),
('compound-growth-q1', 'compound-growth', 'A stock portfolio has a contractual compound interest rate like a bank CD.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Stocks do not promise a rate. Compounding describes a pattern of reinvested returns, which can be negative.', 1),
('compound-growth-q2', 'compound-growth', 'In a smooth positive illustration, compounding is larger than “rate × years” mainly because:', 'mcq', '[{"id":"a","text":"Each period’s gain can earn its own later gain"},{"id":"b","text":"The exchange adds a bonus"},{"id":"c","text":"Inflation is always zero"},{"id":"d","text":"Shares stop trading"}]'::jsonb, '"a"'::jsonb, 'The base grows, so the same percentage is applied to more money. Real years are not smooth.', 2),
('compound-growth-q3', 'compound-growth', 'Which statement is accurate?', 'mcq', '[{"id":"a","text":"Compounding guarantees a profit if you wait long enough"},{"id":"b","text":"A long holding period removes the need to understand risk"},{"id":"c","text":"Reinvested gains can compound, and losses can compound in the other direction"},{"id":"d","text":"Compounding only applies to cash under a mattress"}]'::jsonb, '"c"'::jsonb, 'The math works for negative returns too. A loss reduces the base that future returns apply to.', 3),
('market-cap-s', 'market-cap', 'A company’s share price falls 10% and the share count stays the same. What happens to market cap?', 'mcq', '[{"id":"a","text":"It falls about 10% because price is one of the two inputs"},{"id":"b","text":"It stays the same because the company still exists"},{"id":"c","text":"It becomes equal to this year’s profit"},{"id":"d","text":"It can only change when the company sells new shares"}]'::jsonb, '"a"'::jsonb, 'Market cap moves with price and with the number of shares. A 10% price drop, share count unchanged, is about a 10% smaller market cap.', 0),
('market-cap-q1', 'market-cap', 'Market cap equals:', 'mcq', '[{"id":"a","text":"Share price × shares outstanding"},{"id":"b","text":"Revenue × profit margin"},{"id":"c","text":"Cash minus debt"},{"id":"d","text":"Dividend × number of employees"}]'::jsonb, '"a"'::jsonb, 'The definition is price times share count. Profit and cash are different measures.', 1),
('market-cap-q2', 'market-cap', 'Market cap is the amount of cash the company currently holds.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Cash is on the balance sheet. Market cap is a market price for the equity.', 2),
('market-cap-q3', 'market-cap', 'Two companies have the same market cap. What can you conclude?', 'mcq', '[{"id":"a","text":"They have the same debt"},{"id":"b","text":"They will have the same return next year"},{"id":"c","text":"Their equity has the same current price tag, and little else for certain"},{"id":"d","text":"They are in the same industry"}]'::jsonb, '"c"'::jsonb, 'Equal market caps do not settle debt, industry, or future results.', 3),
('stock-prices-s', 'stock-prices', 'An app shows $100 from an IEX feed at 10:41. Another app shows $100.15 from a consolidated feed a minute later. What is a careful reading?', 'mcq', '[{"id":"a","text":"One of the apps invented a number"},{"id":"b","text":"They can both be real records of different feeds and times"},{"id":"c","text":"The higher number is always the official daily value"},{"id":"d","text":"Prices cannot differ across venues"}]'::jsonb, '"b"'::jsonb, 'Different feeds and timestamps can print different prices. The label and the clock tell you what you are looking at.', 0),
('stock-prices-q1', 'stock-prices', 'Match each price word.', 'match', '[{"term":"Bid","definition":"A posted price where a buyer is willing to buy"},{"term":"Ask","definition":"A posted price where a seller is willing to sell"},{"term":"Last","definition":"The price of the most recent trade"}]'::jsonb, '{"Bid":"A posted price where a buyer is willing to buy","Ask":"A posted price where a seller is willing to sell","Last":"The price of the most recent trade"}'::jsonb, 'Bid and ask are quotes. Last is a trade that already happened.', 1),
('stock-prices-q2', 'stock-prices', 'An IEX price is the same thing as consolidated US market data.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'IEX is one exchange. Consolidated data combines venues. Stak must not relabel one as the other.', 2),
('stock-prices-q3', 'stock-prices', 'Before you treat a number as “the” price, you also need:', 'mcq', '[{"id":"a","text":"The company logo"},{"id":"b","text":"The feed and the timestamp"},{"id":"c","text":"Yesterday’s weather"},{"id":"d","text":"A prediction for next year"}]'::jsonb, '"b"'::jsonb, 'Feed and time tell you what the number represents. Without them, the number is easy to misread.', 3),
('primary-secondary-s', 'primary-secondary', 'You buy 10 shares of a long-listed company in a normal brokerage account. Where does your cash go?', 'mcq', '[{"id":"a","text":"To the company, as if it were a new share sale"},{"id":"b","text":"To the selling shareholder, through the market’s settlement process"},{"id":"c","text":"To the regulator, as a tax"},{"id":"d","text":"It stays in your account and the shares are only a picture"}]'::jsonb, '"b"'::jsonb, 'A normal trade in a listed stock is secondary. You pay the seller, not the company.', 0),
('primary-secondary-q1', 'primary-secondary', 'An IPO is an example of:', 'mcq', '[{"id":"a","text":"The primary market"},{"id":"b","text":"A secondary trade between two funds only"},{"id":"c","text":"A dividend"},{"id":"d","text":"A bond coupon"}]'::jsonb, '"a"'::jsonb, 'The issuer creates and sells new shares in the primary market.', 1),
('primary-secondary-q2', 'primary-secondary', 'When you buy shares on an exchange years after the IPO, the company typically receives the cash from your purchase.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'That purchase is a secondary trade. The seller receives the proceeds.', 2),
('primary-secondary-q3', 'primary-secondary', 'Stak’s simulator is:', 'mcq', '[{"id":"a","text":"A primary offering of Stak shares"},{"id":"b","text":"A secondary-market practice book that does not send orders"},{"id":"c","text":"A broker that holds customer securities"},{"id":"d","text":"An exchange"}]'::jsonb, '"b"'::jsonb, 'Virtual trades are educational records. No issuer, broker, or exchange receives an order from Stak.', 3),
('diversification-s', 'diversification', 'A simulated portfolio holds four stocks, all of them large US banks. Is that broad diversification?', 'mcq', '[{"id":"a","text":"Yes, because there are four tickers"},{"id":"b","text":"No. The holdings still share one sector, so a banking shock can hit all of them"},{"id":"c","text":"Yes, because banks cannot fall together"},{"id":"d","text":"No, because diversification requires exactly 30 stocks"}]'::jsonb, '"b"'::jsonb, 'Count of tickers is not the test. Shared economic exposure is the test.', 0),
('diversification-q1', 'diversification', 'Diversification is meant to reduce:', 'mcq', '[{"id":"a","text":"The risk tied to one company or one bet"},{"id":"b","text":"Every possible loss, including a broad market decline"},{"id":"c","text":"The need to read what you own"},{"id":"d","text":"Taxes in every country"}]'::jsonb, '"a"'::jsonb, 'It targets concentration in a single outcome. A market-wide decline can still hurt a diversified stock portfolio.', 1),
('diversification-q2', 'diversification', 'Owning several companies in the same narrow industry completes diversification.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Those companies can respond to the same customers, regulation, and cycle.', 2),
('diversification-q3', 'diversification', 'Which portfolio is more concentrated?', 'mcq', '[{"id":"a","text":"One stock at 85% of the total and a few small positions"},{"id":"b","text":"Several positions with no single one near the whole portfolio"},{"id":"c","text":"A total-market fund plus a bond fund"},{"id":"d","text":"They are identical because all contain stocks"}]'::jsonb, '"a"'::jsonb, 'The 85% position dominates the result. The other shapes spread the outcome.', 3),
('asset-allocation-s', 'asset-allocation', 'Two simulated portfolios both hold only stock ETFs. One is US, one is international. Have they made different asset allocations?', 'mcq', '[{"id":"a","text":"Yes. International stocks are a different asset class from stocks"},{"id":"b","text":"They differ by region, but both are equity allocations"},{"id":"c","text":"No difference is possible because both are ETFs"},{"id":"d","text":"Cash and stocks are the same asset class"}]'::jsonb, '"b"'::jsonb, 'Region is a real difference inside equities. The asset-class mix is still stocks versus stocks.', 0),
('asset-allocation-q1', 'asset-allocation', 'Asset allocation refers to:', 'mcq', '[{"id":"a","text":"The split across asset types such as stocks, bonds, and cash"},{"id":"b","text":"The hour of the day you trade"},{"id":"c","text":"A company’s dividend date"},{"id":"d","text":"The font on a brokerage statement"}]'::jsonb, '"a"'::jsonb, 'It is the portfolio’s mix of asset types, not a clock setting.', 1),
('asset-allocation-q2', 'asset-allocation', 'There is one asset allocation that is correct for every person.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Time horizon, other money, and tolerance for swings differ. A lesson cannot know them.', 2),
('asset-allocation-q3', 'asset-allocation', 'A portfolio of many stock ETFs and no bonds or cash is best described as:', 'mcq', '[{"id":"a","text":"A bond allocation"},{"id":"b","text":"An equity allocation that may still be diversified by company"},{"id":"c","text":"A guaranteed allocation"},{"id":"d","text":"Cash"}]'::jsonb, '"b"'::jsonb, 'Many stock funds can diversify companies and still leave the portfolio exposed to equity markets.', 3),
('investment-risk-s', 'investment-risk', 'A stock doubled last year. A friend says that proves it was low risk. What is the careful response?', 'mcq', '[{"id":"a","text":"A past gain does not show the range of outcomes that were possible"},{"id":"b","text":"Any stock that rose was risk-free"},{"id":"c","text":"Risk only counts if the price fell"},{"id":"d","text":"Last year’s winner is required to rise again"}]'::jsonb, '"a"'::jsonb, 'The outcome you happened to get is not the full set of outcomes that could have happened.', 0),
('investment-risk-q1', 'investment-risk', 'Which is a fair description of investment risk?', 'mcq', '[{"id":"a","text":"Uncertainty of outcomes, including loss"},{"id":"b","text":"A fee charged by an exchange"},{"id":"c","text":"A guarantee that disappears after one year"},{"id":"d","text":"The company name"}]'::jsonb, '"a"'::jsonb, 'Risk is about uncertain results, not a product label.', 1),
('investment-risk-q2', 'investment-risk', 'If an asset gained money, it cannot have been risky.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A gain is one outcome. The chance of a different outcome is what made it risky.', 2),
('investment-risk-q3', 'investment-risk', 'Inflation risk matters most obviously for:', 'mcq', '[{"id":"a","text":"Cash that might buy less in the future"},{"id":"b","text":"A ticker symbol"},{"id":"c","text":"The color of a chart"},{"id":"d","text":"The number of shares you can read on a screen"}]'::jsonb, '"a"'::jsonb, 'Cash can be stable in dollars and still lose purchasing power.', 3),
('rebalancing-s', 'rebalancing', 'A target mix was 50% stocks. After a rally, stocks are 70% of the simulated portfolio. Rebalancing toward 50% would mean:', 'mcq', '[{"id":"a","text":"Buying more stocks because they went up"},{"id":"b","text":"Reducing the stock weight and increasing the other sleeve"},{"id":"c","text":"Closing the account"},{"id":"d","text":"Ignoring weights because they cannot change"}]'::jsonb, '"b"'::jsonb, 'Rebalancing returns weights toward the target. After stocks outperform, that means reducing the stock share of the mix.', 0),
('rebalancing-q1', 'rebalancing', 'Portfolio weights stay fixed even when prices change.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Weights drift because each holding’s market value changes at a different rate.', 1),
('rebalancing-q2', 'rebalancing', 'The purpose of rebalancing is to:', 'mcq', '[{"id":"a","text":"Restore a chosen mix after drift"},{"id":"b","text":"Guarantee a higher return"},{"id":"c","text":"Pick next year’s best stock"},{"id":"d","text":"Avoid ever selling"}]'::jsonb, '"a"'::jsonb, 'It is a risk-mix maintenance step. It is not a forecast.', 2),
('rebalancing-q3', 'rebalancing', 'A real taxable account adds which consideration that a textbook sketch can skip?', 'mcq', '[{"id":"a","text":"Taxes on realized gains"},{"id":"b","text":"The existence of prices"},{"id":"c","text":"The definition of a share"},{"id":"d","text":"The color of the chart"}]'::jsonb, '"a"'::jsonb, 'Selling winners can create a tax bill. A simulator does not model someone’s tax situation.', 3),
('long-term-s', 'long-term', 'Savings needed for rent in two months are put into a single stock “because long-term investing always works.” What is the mistake?', 'mcq', '[{"id":"a","text":"Two months is a short horizon, and a stock can fall in that window"},{"id":"b","text":"Rent should always be paid in shares"},{"id":"c","text":"Stocks cannot fall in two months"},{"id":"d","text":"A short horizon guarantees a gain"}]'::jsonb, '"a"'::jsonb, 'The phrase “long-term” does not apply to cash that is needed almost immediately.', 0),
('long-term-q1', 'long-term', 'A long time horizon means:', 'mcq', '[{"id":"a","text":"The money is not needed soon"},{"id":"b","text":"Losses are impossible"},{"id":"c","text":"The government insures the shares"},{"id":"d","text":"Prices update once a decade"}]'::jsonb, '"a"'::jsonb, 'Horizon is about when the money is needed. It is not insurance.', 1),
('long-term-q2', 'long-term', 'Holding for many years guarantees a profit on a single stock.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A business can shrink or fail. Time does not repair every company.', 2),
('long-term-q3', 'long-term', 'Why do lessons connect compounding with long horizons?', 'mcq', '[{"id":"a","text":"More years give reinvested gains more chances to earn further gains, if those gains happen"},{"id":"b","text":"Exchanges waive risk after year five"},{"id":"c","text":"Inflation stops"},{"id":"d","text":"Dividends become mandatory"}]'::jsonb, '"a"'::jsonb, 'The math needs both time and actual positive returns. Neither is a promise.', 3),
('volatility-s', 'volatility', 'Portfolio snapshots jump between up days and down days, and end near where they started. Which word fits the path?', 'mcq', '[{"id":"a","text":"Volatile, even though the ending value is similar"},{"id":"b","text":"Risk-free, because it ended flat"},{"id":"c","text":"A dividend"},{"id":"d","text":"A primary offering"}]'::jsonb, '"a"'::jsonb, 'The path swung. Ending near the start does not make the path calm, and it does not make the next path safe.', 0),
('volatility-q1', 'volatility', 'Volatility describes:', 'mcq', '[{"id":"a","text":"How widely values swing"},{"id":"b","text":"The company headquarters"},{"id":"c","text":"A guaranteed coupon"},{"id":"d","text":"The number of shareholders required by law"}]'::jsonb, '"a"'::jsonb, 'It is a description of variation, not an address or a promise.', 1),
('volatility-q2', 'volatility', 'Low recent volatility proves the next month will be calm.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Recent swings are history. They are not a contract about the next month.', 2),
('volatility-q3', 'volatility', 'Why can a flat ending value still be volatile?', 'mcq', '[{"id":"a","text":"The path in between can have large up and down moves"},{"id":"b","text":"Flat results are illegal"},{"id":"c","text":"Volatility only counts at the endpoint"},{"id":"d","text":"Cash is always volatile"}]'::jsonb, '"a"'::jsonb, 'Volatility is about the ride, not only the last point.', 3),
('risk-return-s', 'risk-return', 'A savings illustration pays a stated rate. A stock has no stated rate and can fall 40%. Why might the stock still have a higher expected return in a textbook model?', 'mcq', '[{"id":"a","text":"Because buyers may demand compensation for the chance of that fall"},{"id":"b","text":"Because stocks are insured"},{"id":"c","text":"Because the stock must rise 40% next"},{"id":"d","text":"Because expected means guaranteed"}]'::jsonb, '"a"'::jsonb, 'The extra expected return is compensation for uncertainty. It is not a scheduled payment.', 0),
('risk-return-q1', 'risk-return', 'A higher expected return is a guarantee of a higher actual return.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Expected describes a probability idea. The actual result can be lower, even much lower.', 1),
('risk-return-q2', 'risk-return', 'In the coin illustration, the expected value is $1.50 because:', 'mcq', '[{"id":"a","text":"It is the average of the possible payoffs"},{"id":"b","text":"Every flip pays $1.50"},{"id":"c","text":"The exchange sets the coin price"},{"id":"d","text":"Heads is required"}]'::jsonb, '"a"'::jsonb, 'Expectation is an average across outcomes, not the cash from one outcome.', 2),
('risk-return-q3', 'risk-return', 'Last year’s best-performing asset:', 'mcq', '[{"id":"a","text":"Has already posted that result; it does not owe you a repeat"},{"id":"b","text":"Is now risk-free"},{"id":"c","text":"Must be the best choice for every goal"},{"id":"d","text":"Becomes cash"}]'::jsonb, '"a"'::jsonb, 'A historical return is behind you. The uncertainty that remains is a separate question.', 3),
('bull-bear-s', 'bull-bear', 'A broad market is down 8% from its high. A headline calls it a bear market. Using the common convention, what is off?', 'mcq', '[{"id":"a","text":"Nothing. Any decline is a bear market"},{"id":"b","text":"Commentators often reserve “bear market” for a decline around 20%, and even that is a convention"},{"id":"c","text":"Bear markets only happen to bonds"},{"id":"d","text":"An 8% drop is required to be permanent"}]'::jsonb, '"b"'::jsonb, 'The familiar 20% rule of thumb is a label, and an 8% drop is usually called a correction or a decline, not a bear market.', 0),
('bull-bear-q1', 'bull-bear', 'A bull market is:', 'mcq', '[{"id":"a","text":"A long upward stretch in prices"},{"id":"b","text":"A guaranteed year"},{"id":"c","text":"A type of bank account"},{"id":"d","text":"A dividend"}]'::jsonb, '"a"'::jsonb, 'It names a rising period. It does not insure the next period.', 1),
('bull-bear-q2', 'bull-bear', 'The common 20% bear-market figure is a legal definition that every exchange must follow.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'It is a convention used in market commentary, not a statute.', 2),
('bull-bear-q3', 'bull-bear', 'Why is the label a weak day-to-day signal?', 'mcq', '[{"id":"a","text":"It is assigned by looking back, after much of the move has happened"},{"id":"b","text":"Prices never trend"},{"id":"c","text":"Indexes cannot fall"},{"id":"d","text":"Labels are prices"}]'::jsonb, '"a"'::jsonb, 'You cannot use a backward-looking name as if it were printed on tomorrow’s open.', 3),
('market-cycles-s', 'market-cycles', 'An expansion has lasted longer than the previous one. A post says a recession is therefore due next month. What is the error?', 'mcq', '[{"id":"a","text":"Cycles do not have a fixed length, so age alone does not date the next turn"},{"id":"b","text":"Expansions are illegal after one year"},{"id":"c","text":"Recessions cannot follow expansions"},{"id":"d","text":"Markets and the economy are unrelated"}]'::jsonb, '"a"'::jsonb, 'Length varies. “Due” language pretends the past interval is a contract.', 0),
('market-cycles-q1', 'market-cycles', 'Stock prices always turn on the same day a recession is officially declared.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Markets often move before official dates, and official dates are announced late.', 1),
('market-cycles-q2', 'market-cycles', 'A market cycle is best described as:', 'mcq', '[{"id":"a","text":"A repeating but irregular pattern of stronger and weaker conditions"},{"id":"b","text":"A clock that rings every four years"},{"id":"c","text":"A single stock’s dividend"},{"id":"d","text":"A fee schedule"}]'::jsonb, '"a"'::jsonb, 'The pattern is real enough to study and irregular enough to resist a timer.', 2),
('market-cycles-q3', 'market-cycles', 'Why can share prices fall before a recession shows up in jobs data?', 'mcq', '[{"id":"a","text":"Traders are trying to anticipate future profits"},{"id":"b","text":"Jobs data are prices"},{"id":"c","text":"Companies stop existing at the peak"},{"id":"d","text":"Indexes are required to lead by 30 days"}]'::jsonb, '"a"'::jsonb, 'Prices reflect expectations about future results, so they can move first. They can also be wrong.', 3),
('supply-demand-s', 'supply-demand', 'Many holders decide to sell at once and few new buyers appear. What is the likely immediate effect?', 'mcq', '[{"id":"a","text":"The price they agree tends to fall until buyers are willing to take the shares"},{"id":"b","text":"The price is required to rise because selling is popular"},{"id":"c","text":"The company must issue a dividend"},{"id":"d","text":"Trading stops forever"}]'::jsonb, '"a"'::jsonb, 'More supply of shares for sale, with unchanged demand, is resolved at lower prices.', 0),
('supply-demand-q1', 'supply-demand', 'A last trade price is:', 'mcq', '[{"id":"a","text":"A price where a buyer and a seller met"},{"id":"b","text":"The company’s book value"},{"id":"c","text":"Always yesterday’s close"},{"id":"d","text":"A tax rate"}]'::jsonb, '"a"'::jsonb, 'It is an agreed trade, the meeting point of both sides.', 1),
('supply-demand-q2', 'supply-demand', 'A headline changes the official price even if nobody changes an order.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The price changes when orders and trades change. The headline is only the prompt.', 2),
('supply-demand-q3', 'supply-demand', 'A thinly traded stock can jump more on a small order because:', 'mcq', '[{"id":"a","text":"Fewer shares are posted near the current price"},{"id":"b","text":"Thin stocks have fixed prices"},{"id":"c","text":"Small orders are banned"},{"id":"d","text":"Market cap equals volume"}]'::jsonb, '"a"'::jsonb, 'A thin book means the next posted prices are farther away.', 3),
('company-fundamentals-s', 'company-fundamentals', 'You can recite a stock’s 30-day price path but cannot say what the company sells. What are you missing?', 'mcq', '[{"id":"a","text":"The fundamentals, the business facts behind the ticker"},{"id":"b","text":"Nothing. The path is the business"},{"id":"c","text":"The primary market"},{"id":"d","text":"A dividend guarantee"}]'::jsonb, '"a"'::jsonb, 'Price history without the business is only a record of trades.', 0),
('company-fundamentals-q1', 'company-fundamentals', 'Which item is a fundamental question?', 'mcq', '[{"id":"a","text":"How does this company make money?"},{"id":"b","text":"What color is today’s chart?"},{"id":"c","text":"How many times did the price tick in one second?"},{"id":"d","text":"What is the app icon?"}]'::jsonb, '"a"'::jsonb, 'Fundamentals start with the business model, not the pixel color of a chart.', 1),
('company-fundamentals-q2', 'company-fundamentals', 'A rising chart replaces the need to know what the company sells.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The chart is a price record. The business is a separate set of facts.', 2),
('company-fundamentals-q3', 'company-fundamentals', 'Debt matters in a fundamental read because:', 'mcq', '[{"id":"a","text":"Lenders are paid before common owners"},{"id":"b","text":"Debt erases the share count"},{"id":"c","text":"Debt is a dividend"},{"id":"d","text":"Only banks have customers"}]'::jsonb, '"a"'::jsonb, 'Obligations come ahead of the residual claim that common stock represents.', 3),
('financial-statements-s', 'financial-statements', 'A company reports a profit, but cash from operations is negative. Is that possible?', 'mcq', '[{"id":"a","text":"Yes. Accounting profit and cash collected can diverge"},{"id":"b","text":"No. Profit is defined as cash in the bank"},{"id":"c","text":"Only if the statements are fake"},{"id":"d","text":"Only for ETFs"}]'::jsonb, '"a"'::jsonb, 'Timing of payments, inventory, and non-cash expenses can split profit from operating cash.', 0),
('financial-statements-q1', 'financial-statements', 'Match each statement to its job.', 'match', '[{"term":"Income statement","definition":"Results over a period, from revenue to profit"},{"term":"Balance sheet","definition":"Assets, liabilities, and equity on one date"},{"term":"Cash flow statement","definition":"Where cash came from and where it went"}]'::jsonb, '{"Income statement":"Results over a period, from revenue to profit","Balance sheet":"Assets, liabilities, and equity on one date","Cash flow statement":"Where cash came from and where it went"}'::jsonb, 'Period results, a dated snapshot, and cash movements are three different questions.', 1),
('financial-statements-q2', 'financial-statements', 'The equity line on the balance sheet is the same number as market cap.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Accounting equity is assets minus liabilities. Market cap is price times shares.', 2),
('financial-statements-q3', 'financial-statements', 'Revenue sits on which statement?', 'mcq', '[{"id":"a","text":"The income statement"},{"id":"b","text":"Only the cash flow statement"},{"id":"c","text":"The dividend calendar"},{"id":"d","text":"The bid-ask spread"}]'::jsonb, '"a"'::jsonb, 'Revenue is the top of the income statement. Cash collections are a related but different figure.', 3),
('pe-ratio-s', 'pe-ratio', 'Company A has a P/E of 12 and Company B has a P/E of 30. A post says A is automatically the better investment. What is missing?', 'mcq', '[{"id":"a","text":"The ratio does not say why earnings or expectations differ"},{"id":"b","text":"The lower number is always required to win"},{"id":"c","text":"P/E is a dividend"},{"id":"d","text":"Company B’s ratio is impossible"}]'::jsonb, '"a"'::jsonb, 'A lower P/E is a cheaper price relative to the earnings figure used. It is not a full comparison of the businesses.', 0),
('pe-ratio-q1', 'pe-ratio', 'P/E equals:', 'mcq', '[{"id":"a","text":"Share price / earnings per share"},{"id":"b","text":"Revenue / debt"},{"id":"c","text":"Dividend / interest rate"},{"id":"d","text":"Assets / employees"}]'::jsonb, '"a"'::jsonb, 'The name is literal: price compared with earnings.', 1),
('pe-ratio-q2', 'pe-ratio', 'A forward P/E uses earnings that have already been reported.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Forward uses estimates. Trailing uses reported earnings.', 2),
('pe-ratio-q3', 'pe-ratio', 'A P/E near zero earnings is hard to use because:', 'mcq', '[{"id":"a","text":"Dividing by a tiny earnings number makes the ratio unstable or meaningless"},{"id":"b","text":"The formula forbids prices"},{"id":"c","text":"Utilities cannot have earnings"},{"id":"d","text":"Ratios only work on ETFs"}]'::jsonb, '"a"'::jsonb, 'The denominator is the problem. Tiny or negative earnings break the simple reading.', 3),
('revenue-earnings-s', 'revenue-earnings', 'Revenue rose 20% and profit fell. Which explanation fits the statements?', 'mcq', '[{"id":"a","text":"Costs rose even faster than sales"},{"id":"b","text":"Revenue and profit are the same number"},{"id":"c","text":"The income statement forbids this"},{"id":"d","text":"Margins must have doubled"}]'::jsonb, '"a"'::jsonb, 'Profit is revenue minus costs. Faster cost growth can shrink profit while sales rise.', 0),
('revenue-earnings-q1', 'revenue-earnings', 'Revenue is another word for profit.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Revenue is the top line. Profit is what remains after costs.', 1),
('revenue-earnings-q2', 'revenue-earnings', 'A profit margin is:', 'mcq', '[{"id":"a","text":"Profit divided by revenue"},{"id":"b","text":"Revenue divided by the share price"},{"id":"c","text":"Cash divided by debt"},{"id":"d","text":"The bid minus the ask"}]'::jsonb, '"a"'::jsonb, 'Margin expresses profit as a share of sales.', 2),
('revenue-earnings-q3', 'revenue-earnings', 'Earnings per share can fail to rise even when total earnings rise if:', 'mcq', '[{"id":"a","text":"The company issued enough new shares"},{"id":"b","text":"The price is unchanged"},{"id":"c","text":"Revenue is a liability"},{"id":"d","text":"Margins are a type of bond"}]'::jsonb, '"a"'::jsonb, 'More shares split the profit into smaller claims per share.', 3),
('economic-indicators-s', 'economic-indicators', 'A hot inflation report is released. An app tells every user to sell stocks. What is the educational problem?', 'mcq', '[{"id":"a","text":"A statistic is not a personal trade instruction, and the market may already have moved"},{"id":"b","text":"Inflation figures are secret"},{"id":"c","text":"Unemployment is the same thing as inflation"},{"id":"d","text":"Indicators are illegal to read"}]'::jsonb, '"a"'::jsonb, 'The report is context. A blanket instruction ignores the person’s situation and pretends the number has one market response.', 0),
('economic-indicators-q1', 'economic-indicators', 'Match the indicator.', 'match', '[{"term":"Inflation","definition":"How fast a basket of prices is rising"},{"term":"Unemployment rate","definition":"The share of the labor force without a job and seeking one"},{"term":"GDP","definition":"A measure of the value of production"}]'::jsonb, '{"Inflation":"How fast a basket of prices is rising","Unemployment rate":"The share of the labor force without a job and seeking one","GDP":"A measure of the value of production"}'::jsonb, 'Each series answers a different question about the economy.', 1),
('economic-indicators-q2', 'economic-indicators', 'The first release of an economic series is never revised.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Many series are revised as more complete data arrives.', 2),
('economic-indicators-q3', 'economic-indicators', 'A useful way to treat an indicator is:', 'mcq', '[{"id":"a","text":"As context with a definition, a date, and no personal order attached"},{"id":"b","text":"As a required trade"},{"id":"c","text":"As a dividend"},{"id":"d","text":"As a replacement for company financials"}]'::jsonb, '"a"'::jsonb, 'Definitions and dates keep the number honest. They do not pick a security for you.', 3),
('budgeting-s', 'budgeting', 'After rent, groceries, and a minimum loan payment, $200 is left and payday is three weeks away. What is the budgeting question?', 'mcq', '[{"id":"a","text":"Which remaining jobs can this $200 cover, and which wants wait"},{"id":"b","text":"Which single stock will double before rent is due"},{"id":"c","text":"How to hide the spending so the plan looks perfect"},{"id":"d","text":"Whether a budget forbids food"}]'::jsonb, '"a"'::jsonb, 'A budget is an assignment of limited dollars. Near-term bills come before a market bet.', 0),
('budgeting-q1', 'budgeting', 'Match the budgeting word.', 'match', '[{"term":"Need","definition":"A cost such as housing, food, or a minimum debt payment"},{"term":"Want","definition":"A choice you could delay"},{"term":"Saving","definition":"Money not assigned to this month’s spending"}]'::jsonb, '{"Need":"A cost such as housing, food, or a minimum debt payment","Want":"A choice you could delay","Saving":"Money not assigned to this month’s spending"}'::jsonb, 'The labels separate obligations, choices, and money kept for later.', 1),
('budgeting-q2', 'budgeting', 'A budget is the same document as a brokerage statement.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A budget plans your cash. A brokerage statement lists investments. They answer different questions.', 2),
('budgeting-q3', 'budgeting', 'Tracking spending matters because:', 'mcq', '[{"id":"a","text":"It shows whether the plan matched real life"},{"id":"b","text":"It sets the stock market’s close"},{"id":"c","text":"It replaces the need to earn income"},{"id":"d","text":"It guarantees a surplus"}]'::jsonb, '"a"'::jsonb, 'The comparison of plan and record is what lets you adjust.', 3),
('saving-s', 'saving', 'Someone invests every spare dollar and then cannot cover a car repair without selling shares at a bad time. What was missing?', 'mcq', '[{"id":"a","text":"A separation between money saved for near-term needs and money that can be invested"},{"id":"b","text":"A higher share price"},{"id":"c","text":"A rule against saving"},{"id":"d","text":"More wants in the budget"}]'::jsonb, '"a"'::jsonb, 'Investing money you might need immediately couples a real bill to a market price.', 0),
('saving-q1', 'saving', 'Saving over a month equals:', 'mcq', '[{"id":"a","text":"Income minus spending"},{"id":"b","text":"The change in a stock index"},{"id":"c","text":"Revenue minus earnings"},{"id":"d","text":"Bid minus ask"}]'::jsonb, '"a"'::jsonb, 'It is the unspent gap. Investing is what you might do with it later.', 1),
('saving-q2', 'saving', 'Money that is invested cannot fall in value.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Investing introduces the chance of loss. Saving as cash avoids that market swing and takes on inflation risk instead.', 2),
('saving-q3', 'saving', 'An automatic transfer on payday helps because:', 'mcq', '[{"id":"a","text":"It moves money before casual spending expands"},{"id":"b","text":"It sets the market’s return"},{"id":"c","text":"It removes all bills"},{"id":"d","text":"It is a type of dividend"}]'::jsonb, '"a"'::jsonb, 'The help is behavioral. It does not change what markets will do.', 3),
('emergency-fund-s', 'emergency-fund', 'Essential costs are $2,000 a month. Using the common three-month guideline, how large is the illustration?', 'mcq', '[{"id":"a","text":"$6,000 set aside for essentials, not for a stock purchase"},{"id":"b","text":"$2,000 invested in one company"},{"id":"c","text":"$6,000 of credit-card limit"},{"id":"d","text":"Three shares of an index"}]'::jsonb, '"a"'::jsonb, 'Three months × $2,000 is $6,000. The figure is a guideline applied to this illustration, not personal advice.', 0),
('emergency-fund-q1', 'emergency-fund', 'The job of an emergency fund is to:', 'mcq', '[{"id":"a","text":"Pay a surprise without a new debt or a forced sale"},{"id":"b","text":"Beat the stock market"},{"id":"c","text":"Replace a budget"},{"id":"d","text":"Maximize dividend yield"}]'::jsonb, '"a"'::jsonb, 'Availability is the point. Return is secondary for this pile.', 1),
('emergency-fund-q2', 'emergency-fund', 'A common teaching range is three to six months of essential expenses.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'That range is widely taught. It is a guideline, and essential expenses are the base, not total income.', 2),
('emergency-fund-q3', 'emergency-fund', 'Why is a stock a poor default container for the emergency fund?', 'mcq', '[{"id":"a","text":"The price can be down at the moment you need the cash"},{"id":"b","text":"Stocks are always cash"},{"id":"c","text":"Emergencies are scheduled"},{"id":"d","text":"Prices cannot fall"}]'::jsonb, '"a"'::jsonb, 'The emergency and the market decline do not coordinate their calendars.', 3),
('credit-scores-s', 'credit-scores', 'A card is nearly maxed and a payment was late. Which factors are the score actually reacting to?', 'mcq', '[{"id":"a","text":"Payment history and how much of the limit is used"},{"id":"b","text":"The person’s investing returns"},{"id":"c","text":"The color of the card"},{"id":"d","text":"Whether they have an emergency fund in stocks"}]'::jsonb, '"a"'::jsonb, 'On-time payments and credit utilization are core inputs. Portfolio results are not.', 0),
('credit-scores-q1', 'credit-scores', 'A credit score measures whether you are a good person.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'It summarizes credit-report behavior for lenders. It is not a character grade.', 1),
('credit-scores-q2', 'credit-scores', 'A practical way scores get hurt is:', 'mcq', '[{"id":"a","text":"Late payments and high balances relative to limits"},{"id":"b","text":"Reading a lesson about ETFs"},{"id":"c","text":"Paying a statement in full"},{"id":"d","text":"Having a budget"}]'::jsonb, '"a"'::jsonb, 'Payment history and utilization are the usual pressure points.', 2),
('credit-scores-q3', 'credit-scores', 'Carrying a credit-card balance is:', 'mcq', '[{"id":"a","text":"Required to build credit"},{"id":"b","text":"A way to owe interest, not a requirement for a positive history"},{"id":"c","text":"The same as a dividend"},{"id":"d","text":"Invisible to every scoring model"}]'::jsonb, '"b"'::jsonb, 'On-time payment of the full statement builds a record without interest. A carried balance adds interest.', 3),
('debt-s', 'debt', 'A card charges 20% interest and a practice portfolio is not a promise of 20%. Where does the certain cost sit?', 'mcq', '[{"id":"a","text":"On the card. The 20% is a contractual charge, while a market gain is not contractual"},{"id":"b","text":"On the portfolio, because markets always beat 20%"},{"id":"c","text":"Nowhere. Interest is optional"},{"id":"d","text":"On dividends, which must exceed the card"}]'::jsonb, '"a"'::jsonb, 'Contractual interest is known. An investment return is not. The comparison starts there.', 0),
('debt-q1', 'debt', 'The avalanche method directs extra payments to:', 'mcq', '[{"id":"a","text":"The highest interest rate"},{"id":"b","text":"The smallest balance"},{"id":"c","text":"The newest account, always"},{"id":"d","text":"Whichever lender advertises most"}]'::jsonb, '"a"'::jsonb, 'Avalanche targets the rate. Snowball targets the smallest balance.', 1),
('debt-q2', 'debt', 'A credit-card minimum payment is a fast payoff plan.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Minimums keep the balance outstanding and let interest accumulate. A payoff plan pays more than the minimum.', 2),
('debt-q3', 'debt', 'While using either payoff method, you still:', 'mcq', '[{"id":"a","text":"Pay at least the minimum on every debt"},{"id":"b","text":"Skip payments on the other debts"},{"id":"c","text":"Close every account the same day"},{"id":"d","text":"Convert the debt into shares"}]'::jsonb, '"a"'::jsonb, 'Extra money goes to one target. The others still need their minimums to stay current.', 3),
('interest-rates-s', 'interest-rates', 'A sign says 2% a month. Someone treats it as 2% a year. What went wrong?', 'mcq', '[{"id":"a","text":"The period was ignored. A monthly rate and a yearly rate are different prices"},{"id":"b","text":"Percentages cannot be monthly"},{"id":"c","text":"APR always means per day"},{"id":"d","text":"Interest only applies to stocks"}]'::jsonb, '"a"'::jsonb, 'Always read the period attached to the rate. Two percent each month is not two percent a year.', 0),
('interest-rates-q1', 'interest-rates', 'An interest rate is quoted without a time period and is still unambiguous.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The period is part of the price. Per month and per year are different.', 1),
('interest-rates-q2', 'interest-rates', 'When market interest rates rise, existing fixed-rate bonds tend to:', 'mcq', '[{"id":"a","text":"Fall in price"},{"id":"b","text":"Double their coupon automatically"},{"id":"c","text":"Become stocks"},{"id":"d","text":"Stop counting as debt"}]'::jsonb, '"a"'::jsonb, 'Newer bonds pay more, so the old lower coupon is worth less in the market.', 2),
('interest-rates-q3', 'interest-rates', 'APR is used so borrowers can:', 'mcq', '[{"id":"a","text":"Compare yearly borrowing costs on a more standard basis"},{"id":"b","text":"Ignore fees"},{"id":"c","text":"Skip payments"},{"id":"d","text":"Convert loans into ETFs"}]'::jsonb, '"a"'::jsonb, 'Standardizing the yearly quote makes offers easier to compare. Read what each APR includes.', 3),
('compound-interest-s', 'compound-interest', 'You leave interest inside a savings illustration. Why is year two’s interest larger than year one’s if the rate stays at 5%?', 'mcq', '[{"id":"a","text":"The 5% applies to a balance that already includes year one’s interest"},{"id":"b","text":"The bank is required to raise the rate"},{"id":"c","text":"Inflation sets the rate to 5%"},{"id":"d","text":"Year two is always double"}]'::jsonb, '"a"'::jsonb, 'That is the definition of compounding: the new interest base includes prior interest.', 0),
('compound-interest-q1', 'compound-interest', 'Compound interest means:', 'mcq', '[{"id":"a","text":"Interest calculated on a balance that includes earlier interest"},{"id":"b","text":"A fee that never changes a balance"},{"id":"c","text":"A stock’s dividend guarantee"},{"id":"d","text":"A one-time gift"}]'::jsonb, '"a"'::jsonb, 'The base grows by the interest that was left in place.', 1),
('compound-interest-q2', 'compound-interest', 'Compounding can increase a debt if unpaid interest is added to the balance.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'The math is not only a savings story. It works on balances you owe, too.', 2),
('compound-interest-q3', 'compound-interest', 'Compared with the stated annual rate, compounding monthly rather than yearly:', 'mcq', '[{"id":"a","text":"Changes the result somewhat, and usually less than a large difference in the rate itself"},{"id":"b","text":"Does nothing"},{"id":"c","text":"Doubles the rate by law"},{"id":"d","text":"Applies only to stocks"}]'::jsonb, '"a"'::jsonb, 'Frequency matters. The rate usually matters more.', 3),
('financial-planning-s', 'financial-planning', 'Someone skips rent savings and a high-interest card to practice stock trading with money they need next month. Which planning idea did they skip?', 'mcq', '[{"id":"a","text":"Match the vehicle to the date, and handle known high-cost debt before uncertain returns"},{"id":"b","text":"Always invest cash that has a job this month"},{"id":"c","text":"Plans forbid emergency funds"},{"id":"d","text":"Dates do not matter"}]'::jsonb, '"a"'::jsonb, 'Next month’s rent is a short-dated cash job. A 20% card is a known cost. A stock has neither a date nor a promised return.', 0),
('financial-planning-q1', 'financial-planning', 'A financial goal needs:', 'mcq', '[{"id":"a","text":"A purpose and a time"},{"id":"b","text":"Only a ticker"},{"id":"c","text":"A bull-market label"},{"id":"d","text":"An IPO"}]'::jsonb, '"a"'::jsonb, 'Purpose and timing decide what kind of money it is.', 1),
('financial-planning-q2', 'financial-planning', 'The same dollars should usually serve next month’s rent and a decades-long goal at the same time.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Those jobs have different dates and different tolerance for a market swing.', 2),
('financial-planning-q3', 'financial-planning', 'Why revisit a plan?', 'mcq', '[{"id":"a","text":"Income, debts, and goals change"},{"id":"b","text":"Market vocabulary is illegal to reuse"},{"id":"c","text":"Budgets expire every weekend by law"},{"id":"d","text":"Interest rates never change"}]'::jsonb, '"a"'::jsonb, 'A plan describes a life that moves. The document should move with it.', 3) on conflict (id) do update set lesson_id = excluded.lesson_id, prompt = excluded.prompt, kind = excluded.kind, choices = excluded.choices, answer = excluded.answer, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.achievements (id, title, description, xp) values
('first-lesson', 'First lesson', 'Finish and pass your first lesson.', 20),
('perfect-quiz', 'Perfect quiz', 'Answer every question correctly on a lesson.', 25),
('streak-7', '7-day streak', 'Learn on seven days in a row.', 40),
('streak-30', '30-day streak', 'Learn on thirty days in a row.', 80),
('first-trade', 'First simulated trade', 'Record your first virtual buy or sell.', 15),
('portfolio-explorer', 'Portfolio explorer', 'Open five different asset pages.', 20),
('diversification', 'Diversification practice', 'Meet the portfolio challenge rules in the simulator.', 40),
('lessons-30', '30 lessons', 'Pass thirty lessons.', 60),
('knowledge-milestone', 'Knowledge milestone', 'Reach 500 XP from learning.', 30),
('first-challenge', 'First challenge', 'Complete a daily challenge.', 20),
('path-complete', 'Path complete', 'Pass every lesson in a learning path.', 50) on conflict (id) do update set title = excluded.title, description = excluded.description, xp = excluded.xp;
insert into public.challenges (id, type, title, premium, rules) values
('knowledge-a', 'knowledge', 'Market knowledge', false, null),
('knowledge-b', 'knowledge', 'Market knowledge, second set', false, null),
('portfolio-a', 'portfolio', 'Build a spread-out practice portfolio', true, '{"minHoldings":4,"minSectors":3,"maxWeight":0.4}'::jsonb),
('portfolio-b', 'portfolio', 'Practice portfolio, tighter mix', true, '{"minHoldings":5,"minSectors":3,"maxWeight":0.3,"requireStockAndEtf":true}'::jsonb),
('literacy-a', 'literacy', 'Saving, investing, and spending', false, null),
('literacy-b', 'literacy', 'Interest, debt, and compounding', false, null),
('research-a', 'research', 'Read a business: Costco', true, null),
('research-b', 'research', 'Read a fund: VOO', true, null),
('scenario-a', 'scenario', 'A short-dated bill', true, null),
('scenario-b', 'scenario', 'A concentrated practice account', true, null) on conflict (id) do update set type = excluded.type, title = excluded.title, premium = excluded.premium, rules = excluded.rules;
insert into public.challenge_questions (id, challenge_id, prompt, kind, choices, answer, explanation, sort_order) values
('knowledge-a-1', 'knowledge-a', 'A share of common stock is:', 'mcq', '[{"id":"a","text":"A loan the company must repay on a date"},{"id":"b","text":"An ownership claim"},{"id":"c","text":"A savings-account balance"},{"id":"d","text":"A tax refund"}]'::jsonb, '"b"'::jsonb, 'Common stock is ownership, not a dated loan.', 0),
('knowledge-a-2', 'knowledge-a', 'Buying a long-listed stock on an exchange typically sends your cash to the company.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'That is a secondary trade. The seller receives the proceeds.', 1),
('knowledge-a-3', 'knowledge-a', 'An ETF share is:', 'mcq', '[{"id":"a","text":"A share of a fund"},{"id":"b","text":"Always a single company"},{"id":"c","text":"A central-bank reserve"},{"id":"d","text":"A credit score"}]'::jsonb, '"a"'::jsonb, 'The fund holds the basket. You hold a share of the fund.', 2),
('knowledge-a-4', 'knowledge-a', 'An IEX price is consolidated US market data.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'IEX is one exchange. Consolidated data combines venues.', 3),
('knowledge-a-5', 'knowledge-a', 'Market cap equals:', 'mcq', '[{"id":"a","text":"Price times shares outstanding"},{"id":"b","text":"Cash in the bank"},{"id":"c","text":"This year’s dividend"},{"id":"d","text":"Revenue"}]'::jsonb, '"a"'::jsonb, 'Market cap is a price tag for the equity, not a cash balance.', 4),
('knowledge-b-1', 'knowledge-b', 'A dividend is extra value created on top of an unchanged company.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The cash leaves the company. All else equal, the share price adjusts.', 0),
('knowledge-b-2', 'knowledge-b', 'A trailing P/E uses:', 'mcq', '[{"id":"a","text":"Reported earnings"},{"id":"b","text":"A guess about next decade only"},{"id":"c","text":"The unemployment rate"},{"id":"d","text":"The bid-ask spread"}]'::jsonb, '"a"'::jsonb, 'Trailing means already reported. Forward means an estimate.', 1),
('knowledge-b-3', 'knowledge-b', 'The common bear-market label is:', 'mcq', '[{"id":"a","text":"A convention, often about a 20% decline"},{"id":"b","text":"A statute"},{"id":"c","text":"A dividend rule"},{"id":"d","text":"A credit score"}]'::jsonb, '"a"'::jsonb, 'Commentators use the figure. It is not a law and it is assigned after the move.', 2),
('knowledge-b-4', 'knowledge-b', 'Profit and cash collected are always the same number.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Accounting timing can split profit from operating cash.', 3),
('knowledge-b-5', 'knowledge-b', 'Supply and demand in a stock show up as:', 'mcq', '[{"id":"a","text":"Orders to sell and orders to buy"},{"id":"b","text":"The company logo"},{"id":"c","text":"The emergency fund"},{"id":"d","text":"A budget category"}]'::jsonb, '"a"'::jsonb, 'The trade price is where those orders meet.', 4),
('literacy-a-1', 'literacy-a', 'Saving is:', 'mcq', '[{"id":"a","text":"Income minus spending"},{"id":"b","text":"A guaranteed market return"},{"id":"c","text":"A type of ETF"},{"id":"d","text":"A credit score"}]'::jsonb, '"a"'::jsonb, 'Saving is the unspent gap. Investing is a separate step.', 0),
('literacy-a-2', 'literacy-a', 'Investing and saving are the same action.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'You can save cash without putting it into a security. Investing adds market risk.', 1),
('literacy-a-3', 'literacy-a', 'An emergency fund is mainly:', 'mcq', '[{"id":"a","text":"Cash for a surprise"},{"id":"b","text":"A leveraged stock bet"},{"id":"c","text":"A primary offering"},{"id":"d","text":"A P/E ratio"}]'::jsonb, '"a"'::jsonb, 'The job is availability, not a market return.', 2),
('literacy-a-4', 'literacy-a', 'Spending is:', 'mcq', '[{"id":"a","text":"Using money on goods or services now"},{"id":"b","text":"Always the same as investing"},{"id":"c","text":"A dividend"},{"id":"d","text":"A market cap"}]'::jsonb, '"a"'::jsonb, 'Spending leaves the budget. It is not an ownership claim.', 3),
('literacy-a-5', 'literacy-a', 'Money needed for rent this month is a good default for a single-stock practice with real cash.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A short-dated bill and a volatile asset do not share a time horizon. Stak’s version uses virtual cash only.', 4),
('literacy-b-1', 'literacy-b', 'A rate of 2% per month is the same price as 2% per year.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The period is part of the rate.', 0),
('literacy-b-2', 'literacy-b', 'Compound interest on a savings balance means:', 'mcq', '[{"id":"a","text":"Interest is earned on earlier interest"},{"id":"b","text":"The rate is illegal"},{"id":"c","text":"The balance cannot grow"},{"id":"d","text":"It only applies to stocks"}]'::jsonb, '"a"'::jsonb, 'The base includes interest that was left in the account.', 1),
('literacy-b-3', 'literacy-b', 'The avalanche method targets:', 'mcq', '[{"id":"a","text":"The highest interest rate"},{"id":"b","text":"The smallest logo"},{"id":"c","text":"The newest store card only"},{"id":"d","text":"The lowest balance always"}]'::jsonb, '"a"'::jsonb, 'Avalanche is the interest-rate order. Snowball is the smallest balance.', 2),
('literacy-b-4', 'literacy-b', 'A credit-card minimum payment is designed to clear the balance quickly.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Minimums leave the balance outstanding so interest continues.', 3),
('literacy-b-5', 'literacy-b', 'A credit score is:', 'mcq', '[{"id":"a","text":"A model of credit-report behavior"},{"id":"b","text":"A grade of personal character"},{"id":"c","text":"Your portfolio return"},{"id":"d","text":"An ETF fee"}]'::jsonb, '"a"'::jsonb, 'Lenders use it. It is not a moral score and not an investing score.', 4),
('research-a-1', 'research-a', 'Costco’s shoppers typically:', 'mcq', '[{"id":"a","text":"Pay a membership fee and buy in bulk"},{"id":"b","text":"Receive a bank loan from Costco as the main product"},{"id":"c","text":"Buy only software subscriptions"},{"id":"d","text":"Trade bonds on an exchange"}]'::jsonb, '"a"'::jsonb, 'The description centers on membership warehouses and bulk goods.', 0),
('research-a-2', 'research-a', 'Membership fees are part of how Costco makes money.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'The educational description says fees sit alongside low-margin merchandise sales.', 1),
('research-a-3', 'research-a', 'Which sector label does Stak use for Costco?', 'mcq', '[{"id":"a","text":"Consumer staples"},{"id":"b","text":"Energy"},{"id":"c","text":"US bonds"},{"id":"d","text":"Commodities"}]'::jsonb, '"a"'::jsonb, 'The directory classifies Costco under consumer staples.', 2),
('research-a-4', 'research-a', 'Reading the business description tells you what the share price will do next month.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'A business model is not a price forecast.', 3),
('research-a-5', 'research-a', 'The merchandise side of the model is described as:', 'mcq', '[{"id":"a","text":"Low-margin sales"},{"id":"b","text":"A gold bullion trust"},{"id":"c","text":"A bond index"},{"id":"d","text":"A payments network"}]'::jsonb, '"a"'::jsonb, 'Warehouse retail in the description is low-margin, with fees as the other piece.', 4),
('research-b-1', 'research-b', 'VOO seeks to track:', 'mcq', '[{"id":"a","text":"The S&P 500"},{"id":"b","text":"A bond aggregate"},{"id":"c","text":"The price of gold"},{"id":"d","text":"A single retailer"}]'::jsonb, '"a"'::jsonb, 'The description says VOO tracks the S&P 500.', 0),
('research-b-2', 'research-b', 'VOO and SPY are the same fund.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'They can track the same index and still be different funds, with different managers and expenses.', 1),
('research-b-3', 'research-b', 'Buying VOO means you bought:', 'mcq', '[{"id":"a","text":"A share of the fund"},{"id":"b","text":"The index publisher"},{"id":"c","text":"A bank deposit"},{"id":"d","text":"A membership warehouse"}]'::jsonb, '"a"'::jsonb, 'An ETF purchase is a share of the fund.', 2),
('research-b-4', 'research-b', 'Stak’s description is a recommendation to buy VOO.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'It explains the product. It does not say the fund belongs in any particular account.', 3),
('research-b-5', 'research-b', 'VOO’s asset type in the directory is:', 'mcq', '[{"id":"a","text":"ETF"},{"id":"b","text":"Individual operating company"},{"id":"c","text":"Credit score"},{"id":"d","text":"Savings account"}]'::jsonb, '"a"'::jsonb, 'The directory marks VOO as an ETF.', 4),
('scenario-a-1', 'scenario-a', 'Rent is due in three weeks. The hypothetical person puts the rent money into one stock. The main mismatch is:', 'mcq', '[{"id":"a","text":"The time horizon"},{"id":"b","text":"The color of the chart"},{"id":"c","text":"The ticker’s alphabet position"},{"id":"d","text":"The market cap formula"}]'::jsonb, '"a"'::jsonb, 'Three weeks is a short horizon. A stock can fall inside it.', 0),
('scenario-a-2', 'scenario-a', 'A long-term investing phrase makes a short-term bill safe to place in one company.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The phrase does not change the date the cash is needed.', 1),
('scenario-a-3', 'scenario-a', 'An emergency fund’s job in the hypothetical is to:', 'mcq', '[{"id":"a","text":"Pay the surprise without selling shares in a rush"},{"id":"b","text":"Maximize volatility"},{"id":"c","text":"Replace all insurance"},{"id":"d","text":"Set the P/E of a stock"}]'::jsonb, '"a"'::jsonb, 'Availability is the point of the fund.', 2),
('scenario-a-4', 'scenario-a', 'A 22% credit-card rate compared with a hoped-for market gain is:', 'mcq', '[{"id":"a","text":"A certain cost versus an uncertain return"},{"id":"b","text":"Two guaranteed numbers"},{"id":"c","text":"Irrelevant because rates are yearly"},{"id":"d","text":"A dividend"}]'::jsonb, '"a"'::jsonb, 'The card interest is contractual. The market gain is not.', 3),
('scenario-a-5', 'scenario-a', 'Stak’s virtual trade would pay the rent in this hypothetical.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Virtual cash has no real-world value and cannot pay a bill.', 4),
('scenario-b-1', 'scenario-b', 'A 90% weight in one company means:', 'mcq', '[{"id":"a","text":"That company’s outcome dominates the portfolio"},{"id":"b","text":"The portfolio is fully diversified"},{"id":"c","text":"Market risk has been removed"},{"id":"d","text":"The holding is cash"}]'::jsonb, '"a"'::jsonb, 'Weight, not the number of lessons completed, sets the concentration.', 0),
('scenario-b-2', 'scenario-b', 'Adding three tiny positions automatically removes concentration from a 90% holding.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'The large weight still drives the result.', 1),
('scenario-b-3', 'scenario-b', 'Diversification reduces:', 'mcq', '[{"id":"a","text":"Idiosyncratic risk from one bet"},{"id":"b","text":"Every possible decline including a broad crash"},{"id":"c","text":"The need for a time horizon"},{"id":"d","text":"Taxes in all cases"}]'::jsonb, '"a"'::jsonb, 'It does not erase market-wide declines.', 2),
('scenario-b-4', 'scenario-b', 'An educational note about concentration should avoid:', 'mcq', '[{"id":"a","text":"Telling the person which trade to place"},{"id":"b","text":"Defining concentration"},{"id":"c","text":"Mentioning weights"},{"id":"d","text":"Saying the note is not advice"}]'::jsonb, '"a"'::jsonb, 'Description is allowed. A personal trade instruction is not what these lessons do.', 3),
('scenario-b-5', 'scenario-b', 'Volatility and a permanent loss are the same concept.', 'boolean', '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'Volatility is the size of swings. A permanent loss is capital that does not come back.', 4) on conflict (id) do update set prompt = excluded.prompt, kind = excluded.kind, choices = excluded.choices, answer = excluded.answer, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.assets (symbol, name, asset_type, sector, description) values
('AAPL', 'Apple', 'stock', 'Technology', 'Apple designs consumer electronics, software, and related services. The iPhone is the center of the business, with Mac computers, wearables, and services such as app distribution and cloud storage around it.'),
('MSFT', 'Microsoft', 'stock', 'Technology', 'Microsoft sells software, cloud computing, and business subscriptions. Office, Azure, Windows, and LinkedIn are major pieces. Customers include individuals and large organizations.'),
('GOOGL', 'Alphabet', 'stock', 'Communication', 'Alphabet is the parent of Google. Search advertising is the main business. YouTube, cloud services, and other bets sit beside it. The company is paid largely by advertisers.'),
('AMZN', 'Amazon', 'stock', 'Consumer discretionary', 'Amazon runs a large online store and a cloud-computing business, Amazon Web Services. It also sells subscriptions and devices. Retail and cloud are different engines inside one company.'),
('NVDA', 'NVIDIA', 'stock', 'Technology', 'NVIDIA designs graphics and accelerated-computing chips. Data centers training and running AI models became a large customer group, alongside gaming and professional visualization.'),
('META', 'Meta Platforms', 'stock', 'Communication', 'Meta runs Facebook, Instagram, and WhatsApp. Most of its revenue comes from advertising on those apps. It also spends on virtual-reality hardware and related software.'),
('TSLA', 'Tesla', 'stock', 'Consumer discretionary', 'Tesla makes electric vehicles and energy products such as battery storage. Vehicle sales are the core business. The shares have often moved more sharply than the broad market.'),
('BRK.B', 'Berkshire Hathaway', 'stock', 'Financials', 'Berkshire Hathaway is a holding company. It owns insurers and many operating businesses outright, and it holds a portfolio of publicly traded stocks. The Class B shares are the more widely traded class.'),
('JPM', 'JPMorgan Chase', 'stock', 'Financials', 'JPMorgan Chase is a large US bank. It takes deposits, makes loans, runs credit cards, and operates markets and investment-banking businesses. Its results move with interest rates and credit conditions.'),
('V', 'Visa', 'stock', 'Financials', 'Visa operates a payments network. It earns fees when cards in its network are used. It is not the bank that issues most of the cards, and it does not lend the card balance in the typical transaction.'),
('JNJ', 'Johnson & Johnson', 'stock', 'Health care', 'Johnson & Johnson sells medicines and medical devices. Demand for many of its products is tied to health-care needs rather than to a shopping season.'),
('XOM', 'Exxon Mobil', 'stock', 'Energy', 'Exxon Mobil finds, produces, and refines oil and natural gas, and it sells fuels and chemical products. Profits swing with energy prices.'),
('PG', 'Procter & Gamble', 'stock', 'Consumer staples', 'Procter & Gamble sells household and personal-care products such as detergent, diapers, and toothpaste. Shoppers buy many of these items in both strong and weak economies.'),
('WMT', 'Walmart', 'stock', 'Consumer staples', 'Walmart runs a very large chain of discount stores and a grocery business, plus a growing online storefront. It competes on price and scale.'),
('COST', 'Costco', 'stock', 'Consumer staples', 'Costco is a membership warehouse retailer. Shoppers pay an annual fee and buy groceries and goods in bulk. Membership fees are a meaningful part of how the business makes money, alongside low-margin merchandise sales.'),
('KO', 'Coca-Cola', 'stock', 'Consumer staples', 'Coca-Cola sells beverage concentrates and finished drinks through a global bottling system. The brand portfolio is broader than the cola that carries the company name.'),
('HD', 'Home Depot', 'stock', 'Consumer discretionary', 'Home Depot sells building materials, tools, and home-improvement goods to contractors and households. Housing activity and renovation spending affect the business.'),
('NFLX', 'Netflix', 'stock', 'Communication', 'Netflix sells streaming subscriptions and produces and licenses shows and films. Growth depends on subscribers, pricing, and what it costs to make and buy programming.'),
('DIS', 'Disney', 'stock', 'Communication', 'Disney runs studios, theme parks, consumer products, and streaming. Parks and films are different businesses that can be strong or weak at the same time.'),
('NKE', 'Nike', 'stock', 'Consumer discretionary', 'Nike designs and sells athletic footwear and apparel. It sells through its own stores and through other retailers, and demand is tied to consumer spending and brand strength.'),
('UNH', 'UnitedHealth Group', 'stock', 'Health care', 'UnitedHealth Group runs health-insurance plans and health-services businesses. Policy, medical costs, and enrollment drive the results.'),
('LLY', 'Eli Lilly', 'stock', 'Health care', 'Eli Lilly develops and sells prescription medicines. A small number of large drugs can dominate revenue, which is typical of research-based drug companies.'),
('BAC', 'Bank of America', 'stock', 'Financials', 'Bank of America is a nationwide US bank with consumer banking, wealth management, and global markets businesses. Credit losses and interest rates both matter.'),
('ORCL', 'Oracle', 'stock', 'Technology', 'Oracle sells database software, business applications, and cloud infrastructure. Many customers are large organizations with long-running systems.'),
('AMD', 'AMD', 'stock', 'Technology', 'AMD designs processors and graphics chips for PCs, servers, and gaming. It competes with other chip designers and depends on manufacturers to fabricate the chips.'),
('SPY', 'SPDR S&P 500 ETF Trust', 'etf', 'Broad US equity', 'SPY is an exchange-traded fund that seeks to track the S&P 500 index of large US companies. You are buying a share of the fund, not a share of the index publisher. The traded price is the fund’s market price.'),
('VOO', 'Vanguard S&P 500 ETF', 'etf', 'Broad US equity', 'VOO is an ETF that also seeks to track the S&P 500. It is a different fund from SPY, with its own manager and expenses, aimed at the same index. Similar indexes do not make the funds identical.'),
('QQQ', 'Invesco QQQ Trust', 'etf', 'US growth equity', 'QQQ seeks to track the Nasdaq-100, an index of large non-financial companies listed on Nasdaq. Technology businesses are a large part of that index. It is not the same basket as the S&P 500.'),
('VTI', 'Vanguard Total Stock Market ETF', 'etf', 'Broad US equity', 'VTI seeks to track a very broad index of US stocks, including large, mid-size, and smaller companies. It is still a US equity fund. It does not include a bond allocation.'),
('VXUS', 'Vanguard Total International Stock ETF', 'etf', 'International equity', 'VXUS seeks to track stocks of companies outside the United States, across developed and emerging markets. Currency movements can affect the return a US investor experiences.'),
('BND', 'Vanguard Total Bond Market ETF', 'etf', 'US bonds', 'BND seeks to track a broad index of investment-grade US bonds. Bond prices can fall when interest rates rise. It is not cash, and it is not a stock fund.'),
('AGG', 'iShares Core U.S. Aggregate Bond ETF', 'etf', 'US bonds', 'AGG seeks to track the Bloomberg US Aggregate Bond Index, a wide mix of investment-grade US bonds. Like other bond funds, its price moves with interest rates and credit conditions.'),
('SCHD', 'Schwab US Dividend Equity ETF', 'etf', 'US dividend equity', 'SCHD seeks to track an index of US stocks screened for dividend records and financial measures. Dividends are not guaranteed, and a dividend screen is not the same thing as a broad total-market fund.'),
('XLK', 'Technology Select Sector SPDR', 'etf', 'Technology', 'XLK seeks to track technology companies from the S&P 500. It concentrates the portfolio in one sector. A sector fund can fall even when other parts of the market do not.'),
('XLF', 'Financial Select Sector SPDR', 'etf', 'Financials', 'XLF seeks to track financial companies from the S&P 500, including banks and insurers. The sector is sensitive to interest rates and to credit losses.'),
('XLE', 'Energy Select Sector SPDR', 'etf', 'Energy', 'XLE seeks to track energy companies from the S&P 500. Oil and gas prices are a major driver. Energy can move very differently from technology or consumer staples.'),
('XLV', 'Health Care Select Sector SPDR', 'etf', 'Health care', 'XLV seeks to track health-care companies from the S&P 500, including drug makers, insurers, and device companies. Policy and research outcomes both matter.'),
('IWM', 'iShares Russell 2000 ETF', 'etf', 'US small cap', 'IWM seeks to track the Russell 2000 index of smaller US companies. Smaller companies can be more sensitive to the domestic economy and can swing more than large-cap indexes.'),
('DIA', 'SPDR Dow Jones Industrial Average ETF', 'etf', 'US large cap', 'DIA seeks to track the Dow Jones Industrial Average, a price-weighted index of 30 large US companies. It is narrower than a total-market fund and is not the same as the S&P 500.'),
('VNQ', 'Vanguard Real Estate ETF', 'etf', 'Real estate', 'VNQ seeks to track US real-estate investment trusts. REITs own or finance property and must distribute most taxable income. The fund can react to both property markets and interest rates.'),
('GLD', 'SPDR Gold Shares', 'etf', 'Commodities', 'GLD seeks to reflect the price of gold bullion, less expenses. It is not a stock basket and it does not produce a dividend from a business. Gold prices have their own drivers.') on conflict (symbol) do update set name = excluded.name, asset_type = excluded.asset_type, sector = excluded.sector, description = excluded.description;
